if not tower or not hall or not door: raise RuntimeError('anchors ausentes')
T=tower.matrix_world.translation.xy.copy(); H=hall.matrix_world.translation.xy.copy(); D=door.matrix_world.translation.xy.copy(); EX=(H-T).normalized(); EY=Vector((-EX.y,EX.x))
def pts(o):
    if o.type=='MESH' and o.data and len(o.data.vertices): return [o.matrix_world@v.co for v in o.data.vertices]
    if o.type=='CURVE' and o.data:
        out=[]
        for sp in o.data.splines:
            if len(sp.bezier_points): out.extend([o.matrix_world@bp.co for bp in sp.bezier_points])
            else: out.extend([o.matrix_world@Vector((p.co.x,p.co.y,p.co.z)) for p in sp.points])
        if out:return out
    return [o.matrix_world@Vector(c) for c in o.bound_box]
def sm(o):
